import{mkdir,rm,stat,utimes}from"node:fs/promises";import{isErrnoCode}from"#shared/guards.js";import{dirname,join}from"node:path";function resolveExtensionBuildLockPath(e){return join(e,`.eve`,`locks`,`extension-build.lock`)}async function withExtensionBuildLock(e,t){let n=resolveExtensionBuildLockPath(e);await acquireExtensionBuildLock(n,e);let r=setInterval(()=>{let e=new Date;utimes(n,e,e).catch(()=>void 0)},2e3);r.unref();try{return await t()}finally{clearInterval(r),await rm(n,{force:!0,recursive:!0})}}async function acquireExtensionBuildLock(e,t){let n=Date.now()+6e5;for(await mkdir(dirname(e),{recursive:!0});;){try{await mkdir(e);return}catch(e){if(!isErrnoCode(e,`EEXIST`))throw e}let r=(await stat(e).catch(()=>void 0))?.mtimeMs;if(r!==void 0&&Date.now()-r>=3e4)await rm(e,{force:!0,recursive:!0});else{if(Date.now()>=n)throw Error(`Timed out after 10 minutes waiting for another eve process to finish building the extension at ${t}. If no other build is running, delete ${e} and retry.`);await new Promise(e=>setTimeout(e,100))}}}export{resolveExtensionBuildLockPath,withExtensionBuildLock};